const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={library:'M4 4h6v7H4z M14 4h6v7h-6z M4 15h6v5H4z M14 15h6v5h-6z',scripts:'M5 3h12l3 3v15H5z M9 8h7 M9 12h7 M9 16h4',daily:'M4 4h16v16H4z M4 9h16 M8 2v4 M16 2v4 M8 13h2 M14 13h2 M8 17h2',review:'M12 3l9 4v6c0 5-9 9-9 9S3 18 3 13V7z M8 12l3 3 5-6',performance:'M4 20V10h4v10 M10 20V4h4v16 M16 20v-7h4v7',scriptperf:'M4 19h16 M6 15l4-6 4 3 5-8',lineage:'M12 3v6 M5 14v-5h14v5 M2 14h6v6H2z M16 14h6v6h-6z M9 2h6v4H9z',tags:'M3 4h9l9 9-8 8-10-9z M7 8h.1',mapping:'M9 7H6a5 5 0 000 10h3 M15 7h3a5 5 0 010 10h-3 M8 12h8',settings:'M12 8a4 4 0 100 8 4 4 0 000-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const icon=n=>`<span class="icon"><svg viewBox="0 0 24 24"><path d="${icons[n]||icons.library}"/></svg></span>`;
const nav=[['library','素材库'],['scripts','脚本库'],['candidates','脚本候选'],['daily','每日制作报表'],['weekly','每周方向复盘'],['review','集中复核'],['performance','素材表现'],['scriptperf','脚本表现'],['lineage','裂变表现'],['tags','标签分析'],['mapping','数据关联'],['settings','设置']];
const classes=['新脚本首批','脚本裂变','成片裂变','待分类'], colors=['#638bea','#a28bd0','#68b4a1','#d9b76d'];
let state, page=location.hash.slice(1)||'library', product=localStorage.getItem('product')||'live', date=new Date(Date.now()+8*3600000).toISOString().slice(0,10), search='', category='', mode='list', perfMode='front', reviewTab='全部', tagSelected=[], tagOp='AND', scriptFilter='', lineageType='asset', descendants=false, mappingSearch='', mappingPage=0, mappingBucket='', tagSource='confirmed';
const num=v=>v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:0}), money=v=>v==null?'—':(product==='demo'?'$':'')+Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}), pct=v=>v==null?'—':(v*100).toFixed(2)+'%';
const localdate=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const badge=(s)=>`<span class="badge ${({'新脚本首批':'blue','脚本裂变':'purple','成片裂变':'green','待分类':'amber','已分析':'green','分析中':'blue','未分析':'gray','等待分析':'amber','完成':'green','待复核':'amber','分析失败':'red','排队':'amber','内容分析':'blue','等待批次提交':'gray','等待服务':'gray','值得裂变':'green','数据不足':'amber','规则未配置':'gray'})[s]||'gray'}">${esc(s||'—')}</span>`;
const analysisLabel=a=>({pending:'未分析',queued:'等待分析',running:'分析中',completed:'已分析',failed:'分析失败'}[a.analysis_status]||(a.analysis_id||a.state==='完成'||a.state==='待复核'?'已分析':a.state==='分析失败'?'分析失败':'未分析'));
const analysisBadge=a=>`<span data-analysis-id="${esc(a.id)}">${badge(analysisLabel(a))}</span>`;
