async function api(path,body){if(body)body={...body,product};const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function refresh(){try{state=await api(`/api/state?product=${encodeURIComponent(product)}&date=${date}`);render()}catch(e){toast(e.message)}}
function go(p){page=p;search='';category='';scriptFilter='';designerFilter='';location.hash=p;render()}
