setInterval(async()=>{if(!state||statusPolling||document.hidden)return;statusPolling=true;const requestedProduct=product;try{const update=await api(`/api/analysis-status?product=${encodeURIComponent(product)}`);if(product!==requestedProduct)return;let changed=false;for(const next of update.assets){const a=state.assets.find(x=>x.id===next.id);if(!a)continue;if(['analysis_status','analysis_id','analysis_error','state'].some(k=>a[k]!==next[k]&&(a[k]!=null||next[k]!=null))){Object.assign(a,next);changed=true;document.querySelectorAll('[data-analysis-id]').forEach(el=>{if(el.dataset.analysisId===a.id)el.innerHTML=badge(analysisLabel(a))})}}if(page!=='candidates'&&(changed||state.integrations.doris?.status==='syncing')&&!$('#overlay').children.length&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))await refresh()}catch{}finally{statusPolling=false}},3000);

setInterval(()=>{if(document.hidden)return;document.querySelectorAll('.cover-pending img').forEach(img=>{img.src=img.src.split('?')[0]+'?retry='+Date.now()})},5000);

function creativeBreakdown(a,r){const c=r.creative_analysis;if(!c)return '';const frames=r.frames||[];const picks=frames.length<=5?frames:Array.from({length:5},(_,i)=>frames[Math.round(i*(frames.length-1)/4)]);const text=v=>typeof v==='string'?v:v?.observation||'证据不足';const facts=state.facts.filter(f=>f.bucket==='single'&&f.asset_id===a.id);const m=facts.length?calc(facts):null;return `<section class="story-report"><h2>${esc(r.script_title||'剧情分析')}</h2><p class="story-intro">${esc(r.summary)}</p><div class="story-frames">${picks.map(f=>`<button data-seek="${f.at}"><img src="/frames/${r.id}/${f.file}" alt="${f.at}秒关键帧"><span>${Number(f.at).toFixed(1)} 秒</span></button>`).join('')}</div><div class="story-metrics">${m?`已关联素材合计：花费 ${money(m.spend)} / 展示 ${num(m.impressions)} / 点击 ${num(m.clicks)} / 安装 ${num(m.installs)} / CTR ${pct(m.ctr)} / CPI ${money(m.cpi)} · D0 暂无已确认口径`:'尚未关联投放数据。'}</div><div class="story-columns"><div><h3>画面与字幕中的脚本</h3><ol>${(c.timeline||[]).filter(t=>!/CTA|落版|下载|品牌收束/i.test(t.stage)).map(t=>`<li><strong>约 ${Number(frames[t.start_frame]?.at||0).toFixed(1)}–${Number(frames[t.end_frame]?.at||0).toFixed(1)} 秒</strong><p>${esc(t.visible_script)}</p></li>`).join('')}</ol></div><div><h3>剧情表现形式</h3><p>${esc(text(c.presentation))}</p><h3>剧情人物造型</h3><p>${esc(text(c.character_styling))}</p></div></div>${c.conclusion?`<h3>总结分析</h3><p>${esc(c.conclusion)}</p>`:''}<p class="muted">基于采样画面，未分析音轨，分段时间为近似范围。</p></section>`}

function creativeDataContext(a){const facts=state.facts.filter(f=>f.bucket==='single'&&f.asset_id===a.id);if(!facts.length)return '<div class="notice">尚无已确认关联的投放记录。本次仅评价可见创意，不判断获客成本、付费表现或是否值得扩量。</div>';return `<div class="notice">按已确认素材 × 渠道汇总，先加总分子分母再计算；不混用媒体安装与 Adjust 安装。数据解释与内容证据独立。</div>${[...new Set(facts.map(f=>f.channel))].map(channel=>{const rows=facts.filter(f=>f.channel===channel),m=calc(rows);return `<div class="creative-observation"><h3>${esc(channel||'未知渠道')} · ${rows.length} 条投放记录</h3><p>来源花费 ${money(m.spend)} / 展示 ${num(m.impressions)} / 点击 ${num(m.clicks)} / CTR ${pct(m.ctr)}</p><div class="muted">当前本地存量安装为 Adjust 归因，不能据此计算媒体 CVR / CPI。D0 未完成可比口径关联时不做回收排名。国家、受众、日期与 Campaign 未受控，不能把表现差异归因于某种外貌或镜头。</div><details><summary>查看 Campaign / 素材 ID 明细</summary>${rows.map(f=>`<p class="muted">${esc(f.date)} / ${esc(f.country)} / Campaign ${esc(f.source_dimensions?.campaign_id||'未知')} / 素材 ${esc(f.creative_id||a.id)} / 花费 ${money(f.spend)}</p>`).join('')}</details></div>`}).join('')}`}

