function structuredTagSection(r){const a=r.structured_tags?.assets?.[0];if(!a)return '';const format=v=>(Array.isArray(v)?v:[v]).map(x=>`${esc(companionTagLabels[x]||({'unspecified':'证据不足','not_applicable':'不适用','other':'词库外候选'}[x])||x)} <code>${esc(x)}</code>`).join(' / ');return `<details class="structured-tags"><summary>查看 v1.1 结构化标签与证据（待复核）</summary>${Object.entries(a.tags).map(([k,v])=>`<p><strong>${esc(k)}</strong>：${format(v)}</p>`).join('')}${a.characters.map(c=>`<h4>${esc(c.role_reference)}</h4>${['occupation','identities','visual_style','archetypes'].map(k=>`<p>${esc(k)}：${format(c[k])}</p>`).join('')}${Object.entries(c.appearance).map(([k,v])=>`<p>${esc(k)}：${format(v)}</p>`).join('')}`).join('')}<h4>关系</h4>${a.relationships.map(x=>`<p>${esc(x.participants.join(' / '))}：${format(x.relationship_status)} / ${format(x.romance_tropes)}</p>`).join('')}<h4>证据</h4>${a.evidence.map(e=>`<p><code>${esc(e.field)} → ${esc(e.label)}</code><br>${esc(e.timestamp_start)} 秒 · ${esc(e.source)} · ${esc(e.confidence)}<br>${esc(e.observation)}</p>`).join('')}<h4>复核项</h4>${a.review.items.map(x=>`<p>${esc(x.field)}：${esc(x.detail)}</p>`).join('')}<h4>词库候选</h4>${a.vocabulary_candidates.map(x=>`<p>${esc(x.label_zh)} (${esc(x.proposed_id)})：${esc(x.definition)}</p>`).join('')||'暂无'}</details>`}

function integrationPanel(){const c=state.capabilities||{};return `<section class="panel"><div class="panel-head"><h2>本机服务状态</h2></div><div class="quality-list">${[['视频处理',c.ffmpeg?'FFmpeg 可用':'未安装 FFmpeg，请安装后重试'],['视觉分析',c.analysis?'已配置采样画面分析服务':'未配置 · 仅生成封面与关键帧'],['Doris 同步',c.doris?'已配置只读适配器':'未配置 · 可先导入 JSON']].map(([k,v])=>`<div class="quality-row"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div class="settings-body"><button id="import-facts">导入投放 JSON</button><p class="muted">服务地址和授权通过服务端环境变量配置，详见项目 README。上传、复核和报表不依赖外部服务。</p></div></section>`}
function importFacts(){overlay(`<div class="drawer-head"><h2>导入投放数据</h2><button id="close" class="ghost" aria-label="关闭">✕</button></div><div class="drawer-body"><div class="notice">选择包含 facts 数组的 JSON 文件。必需字段：date、channel、country、creative_id、spend。可附带 cohorts 数组。重复事实更新指标并保留人工映射。<a href="/example-facts.json" download>下载格式样例（虚构数据）</a></div><input id="facts-file" type="file" accept=".json,application/json"><button id="facts-submit" class="primary">导入当前产品</button><p id="facts-result" role="status"></p></div>`);$('#facts-submit').onclick=async()=>{const file=$('#facts-file').files[0];if(!file)return toast('请选择 JSON 文件');const button=$('#facts-submit');button.disabled=true;try{const data=JSON.parse(await file.text());const r=await api('/api/facts/import',data);close();await refresh();toast(`已导入 ${r.imported} 条，当前共 ${r.total} 条`)}catch(e){$('#facts-result').textContent=e.message;button.disabled=false}}}

let v6Category='一级分类';
function tags(){const dict=state.v6_dictionary||[];const g=dict.find(g=>g.category===v6Category)||dict[0];if(!g)return legacyTags();const ready=state.assets.filter(a=>a.v6?.status==='ready');const groups=g.tags.map(t=>({name:t.label+' / '+(t.english_full||t.canonical),assets:ready.filter(a=>a.v6.tags[g.category]?.includes(t.code))})).filter(g=>g.assets.length);perfMode='front';return title('V6 大类分析','按 15 个大类汇总已完成命名的素材；中文 / English 全名展示。')+`<div class="notice">已完成 V6 命名 ${ready.length} / ${state.assets.length} 条。待核对项不进入正式统计。同类多标签可能重叠，各行不可直接相加。</div><section class="panel"><div class="toolbar"><select id="v6-category" aria-label="V6 分析大类">${dict.map(x=>`<option value="${esc(x.category)}" ${x.category===g.category?'selected':''}>${esc(x.category)} / ${esc(x.english)}</option>`).join('')}</select></div>${groups.length?perfRows(groups):empty('该大类暂无已确认素材','上传视频并完成 V6 画面、字幕与语音核对。')}</section>`}
